function tpDistance(a,b){const row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let prev=row[0];row[0]=i;for(let j=1;j<=b.length;j++){const old=row[j];row[j]=Math.min(row[j]+1,row[j-1]+1,prev+(a[i-1]===b[j-1]?0:1));prev=old}}return row[b.length]}
function tpSuggestion(word,candidates){let best='',score=Infinity;for(const item of candidates){const distance=tpDistance(word,item);if(distance<score){best=item;score=distance}}return score<=Math.max(1,Math.floor(word.length/3))?best:''}
